def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    border_cells = set()
    for c in range(w):
        if grid[0][c] != bg: border_cells.add((0,c))
        if grid[h-1][c] != bg: border_cells.add((h-1,c))
    for r in range(h):
        if grid[r][0] != bg: border_cells.add((r,0))
        if grid[r][w-1] != bg: border_cells.add((r,w-1))
    border_colors = {grid[r][c] for r,c in border_cells}
    markers = [v for v in counts if v != bg and v not in border_colors]
    if not markers: return [row[:] for row in grid]
    mark = markers[0]
    out = [row[:] for row in grid]
    # Identify contiguous non-background runs on horizontal edges and propagate
    # inward from the center column(s) of each run.
    for edge, direction in ((0, 1), (h-1, -1)):
        c = 0
        while c < w:
            if grid[edge][c] == bg:
                c += 1; continue
            color = grid[edge][c]
            j = c+1
            while j < w and grid[edge][j] == color: j += 1
            # Only horizontal bars (length > 1) serve as ray origins.
            if j-c > 1:
                centers = range(c+(j-c-1)//2, c+(j-c)//2+1)
                for col in centers:
                    r = edge + direction
                    while 0 <= r < h:
                        if grid[r][col] == mark:
                            out[r][col] = 4
                            break
                        if grid[r][col] == bg:
                            out[r][col] = mark
                        r += direction
            c = j
    return out
